from typing import Literal

from pydantic import BaseModel

from churnlens.segmentation.summary import HIGH_PRIORITY_SHARE, MEDIUM_PRIORITY_SHARE

METHOD_NOTE = (
    "Segments come from K-Means clustering on behaviour features only (tenure, monthly charges, "
    "add-on services, contract length and internet type). Churn was not used to build them: "
    "observed churn rates are measured afterwards. Persona names are generated by rules from each "
    "cluster's averages and describe groups, not individual customers."
)
PRIORITY_NOTE = (
    "Retention priority ranks segments by their share of 12-month revenue at risk (churn "
    "probability x monthly charges x 12 months: a model-based estimate in revenue, not profit). "
    f"Tiers are display cutoffs chosen by the author (High: {HIGH_PRIORITY_SHARE:.0%} or more of "
    f"revenue at risk, Medium: {MEDIUM_PRIORITY_SHARE:.0%} or more), not statistical thresholds."
)


class Characteristics(BaseModel):
    avg_tenure_months: float
    avg_add_on_services: float
    avg_contract_months: float
    share_fiber: float
    share_dsl: float
    share_no_internet: float
    share_of_churned_revenue_historical: float


class SegmentOut(BaseModel):
    cluster_id: int
    persona_name: str
    description: str | None
    size: int
    share_of_customers: float
    observed_churn_rate: float
    avg_monthly_charges: float
    revenue_at_risk_12m: float
    share_of_revenue_at_risk: float
    retention_priority: int
    priority_tier: Literal["High", "Medium", "Low"]
    characteristics: Characteristics | None


class SegmentList(BaseModel):
    analysis_run_id: int
    total_customers: int
    method_note: str = METHOD_NOTE
    priority_note: str = PRIORITY_NOTE
    segments: list[SegmentOut]